"""Kunci OSCE — endokrin, metabolik & gizi (8)."""
from osce_lib import ADULT, AND, AV, CASE, CHILD, E, IT, NP, NT, O, PCT_ADULT, PPK, T, W

REF = [PPK, "PERKENI. Pedoman Pengelolaan dan Pencegahan Diabetes Melitus (2021)"]
META = "Penyakit Dalam — keluhan berkemih & metabolik"
GIZI = "Penyakit Dalam/Anak — gizi & metabolik"

CASE("dm_tipe1", META, [],
     [NP("rujuk", "Rujuk ke dokter spesialis anak/penyakit dalam untuk inisiasi insulin"),
      NP("kad", "Pasang infus NaCl 0,9% & rujuk segera (ketoasidosis diabetik)", when=T("kad")),
      NP("diet", "Diet seimbang sesuai kebutuhan tumbuh kembang & aktivitas fisik teratur"),
      NP("psikososial", "Dukungan psikososial untuk keluarga & sekolah"),
      NP("stop_makan", "Hentikan semua makanan manis & nasi agar gula turun tanpa insulin", "berbahaya", "Ketoasidosis & malnutrisi; DM tipe 1 wajib insulin.")],
     [E("dx", "Ini diabetes tipe 1: tubuh tidak lagi memproduksi insulin", "diagnosis"),
      E("obat", "Pengobatan utama adalah suntikan insulin seumur hidup, dimulai oleh dokter spesialis", "pengobatan"),
      E("bahaya", "Segera ke IGD bila muntah, nyeri perut, napas cepat-dalam, napas berbau buah, lemas/mengantuk, atau gemetar-berkeringat-bingung (hipoglikemia)", "tanda_bahaya"),
      E("kontrol", "Kontrol rutin bersama spesialis & pemantauan gula darah mandiri", "kontrol"),
      E("tablet", "Bisa diobati dengan obat minum seperti diabetes orang tua", "pengobatan", "pengecoh", "DM tipe 1 tidak responsif terhadap obat oral.")],
     avoid=[AV("Obat antidiabetes oral tidak efektif & menunda insulin pada DM tipe 1.", classes=["antidiabetes"], sev="kritis")],
     note="Inisiasi insulin dilakukan spesialis — tugas FKTP: diagnosis, stabilisasi, edukasi, & rujukan.", refs=REF + ["IDAI. Konsensus DM Tipe 1 pada Anak (2017)"])

CASE("hipoglikemia", META,
     [IT("dekstrosa", "Dekstrosa 40% IV", "opsional", "Hanya bila tidak sadar/tidak dapat menelan.", [O("dekstrosa", "Dekstrosa 40% 25–50 mL (10–20 g) IV bolus", (10, 20), "tunggal")])],
     [NP("glukosa", "Beri 15–20 g glukosa oral (gula/teh manis), cek ulang 15 menit & ulangi bila masih rendah"),
      NP("makan", "Setelah normal, makan karbohidrat kompleks"),
      NP("obat", "Tinjau & sesuaikan obat penurun gula (ganti sulfonilurea kerja panjang/kurangi dosis insulin)"),
      NP("ginjal", "Perhatikan fungsi ginjal dalam penyesuaian obat", when=T("gangguan_ginjal")),
      NP("insulin_lagi", "Lanjutkan dosis obat diabetes seperti biasa malam ini", "berbahaya", "Hipoglikemia berulang (terutama sulfonilurea).")],
     [E("dx", "Ini hipoglikemia: gula darah terlalu rendah, sering akibat obat diabetes & telat makan", "diagnosis"),
      E("obat", "Obat diabetes disesuaikan; jangan melewatkan makan setelah minum obat", "pengobatan"),
      E("bahaya", "Bila gemetar, keringat dingin, berdebar, atau bingung: segera makan/minum manis; ke IGD bila tidak sadar", "tanda_bahaya"),
      E("kontrol", "Kontrol 1 minggu untuk evaluasi obat & gula darah", "kontrol"),
      E("permen", "Selalu bawa permen/gula", "pencegahan"),
      E("kurangi_makan", "Kurangi makan agar gula darah tetap terkendali", "pencegahan", "berbahaya", "Memicu hipoglikemia berulang.")],
     avoid=[AV("Sulfonilurea memperberat/memperpanjang hipoglikemia.", groups=["sulfonilurea"]),
            AV("Memberi insulin saat hipoglikemia membahayakan.", classes=["insulin"], sev="kritis")],
     note="Pasien sadar: koreksi dengan glukosa oral (bukan resep). Dekstrosa IV hanya bila tidak dapat menelan.", refs=REF)

CASE("malnutrisi_energi_protein", GIZI,
     [IT("ab", "Antibiotik", "utama", "Gizi buruk: antibiotik rutin (infeksi tersembunyi).",
         [O("amoksisilin", "Amoksisilin 15–25 mg/kgBB/kali 2–3 × sehari selama 5 hari", None, "rutin", (2, 3), (5, 5), forms=["amoksisilin-syr125", "amoksisilin-syr250"], perkg=(13, 27)),
          O("kotrimoksazol", "Kotrimoksazol 4 mg TMP/kgBB/kali 2 × sehari selama 5 hari", None, "rutin", (2, 2), (5, 5), forms="kotrimoksazol-syr", perkg=(18, 30)),
          O("eritromisin", "Eritromisin 10–12,5 mg/kgBB/kali 4 × sehari selama 5 hari", None, "rutin", (4, 4), (5, 5), forms="eritromisin-syr200", perkg=(9, 14))],
         T("gizi_buruk")),
      IT("vit_a", "Vitamin A", "pendukung", "Gizi buruk: vitamin A dosis sesuai umur.",
         [O("vitamin_a", "Vitamin A 100.000 IU (6–11 bulan) / 200.000 IU (≥ 12 bulan) dosis tunggal", (100000, 200000), "tunggal")], T("gizi_buruk")),
      IT("folat", "Asam folat", "pendukung", "Gizi buruk.", [O("asam_folat", "Asam folat 1 mg/hari (hari pertama 5 mg)", (1, 5), "rutin", (1, 1), (7, 14), forms="asamfolat-tab1")], T("gizi_buruk")),
      IT("zinc", "Zinc", "pendukung", "Diare berulang.", [O("zinc", "Zinc 10–20 mg 1 × sehari selama 10 hari", (10, 20), "rutin", (1, 1), (10, 10))], T("diare_berulang"))],
     [NP("pmt", "PMT pemulihan & konseling MPASI padat gizi (protein hewani)"),
      NP("f75", "Rujuk ke pusat pemulihan gizi (F-75 → F-100/RUTF, 10 langkah)", when=T("gizi_buruk")),
      NP("hangat", "Jaga bayi tetap hangat & cegah hipoglikemia (beri makan sering) selama rujukan", when=T("gizi_buruk")),
      NP("tb", "Skrining TB anak (kontak & batuk lama)", when=T("tb_curiga")),
      NP("pantau", "Pantau BB & z-skor berkala; stimulasi tumbuh kembang"),
      NP("tajin", "Ganti susu/MPASI dengan air tajin & teh manis", "berbahaya", "Miskin protein — memperberat malnutrisi.")],
     [E("dx", "Anak mengalami kekurangan gizi (berat badan tidak sesuai tinggi badan)", "diagnosis"),
      E("obat", "Pemulihan utama dengan makanan bergizi tinggi protein; obat sesuai kebutuhan", "pengobatan"),
      E("bahaya", "Segera ke fasilitas kesehatan bila anak tidak mau makan/minum, muntah terus, diare, sesak, sangat lemas, bengkak, atau dingin", "tanda_bahaya"),
      E("kontrol", "Kontrol & timbang tiap 1–2 minggu", "kontrol"),
      E("cegah", "Lengkapi imunisasi & posyandu rutin tiap bulan", "pencegahan"),
      E("vitamin_saja", "Cukup diberi vitamin penambah nafsu makan", "pengobatan", "pengecoh", "Tidak menggantikan asupan energi-protein.")],
     note="Gizi kurang tanpa gizi buruk: tatalaksana gizi (PMT, konseling) tanpa obat rutin.", refs=[PPK, "Kemenkes RI. Pedoman Pencegahan & Tata Laksana Gizi Buruk pada Balita (2019)"])

CASE("defisiensi_vitamin", GIZI,
     [IT("tiamin", "Tiamin", "utama", "Beri-beri.", [O("tiamin", "Tiamin 50–100 mg 1 × sehari selama 2–4 minggu", (50, 100), "rutin", (1, 2), (14, 30))], T("beriberi")),
      IT("vit_c", "Vitamin C", "utama", "Skorbut.", [O("vitamin_c", "Vitamin C 500–1000 mg/hari selama 2–4 minggu", (500, 1000), "rutin", (1, 2), (14, 30), forms="vitc-tab500")], T("skorbut")),
      IT("b_kompleks", "Vitamin B kompleks", "utama", "Defisiensi riboflavin/B kompleks.", [O("vitamin_b_kompleks", "Vitamin B kompleks 3 × 1 tablet selama 2–4 minggu", 1, "rutin", (2, 3), (14, 30))], T("b_kompleks"))],
     [NP("gizi", "Gizi seimbang: lauk, sayur, buah; beras tidak disosoh berlebihan"),
      NP("alkohol", "Hentikan konsumsi alkohol", when=T("alkohol")),
      NP("masak", "Masak sayur sebentar agar vitamin tidak rusak"),
      NP("suplemen_dosis_tinggi", "Minum semua vitamin dosis sangat tinggi jangka panjang tanpa pengawasan", "berbahaya", "Risiko toksisitas (mis. vitamin A, D).")],
     [E("dx", "Keluhan disebabkan kekurangan vitamin akibat pola makan", "diagnosis"),
      E("obat", "Vitamin diminum sesuai dosis & diikuti perbaikan pola makan", "pengobatan"),
      E("bahaya", "Segera kembali bila sesak, bengkak kaki, berdebar, kesemutan/lemah tungkai berat, atau perdarahan", "tanda_bahaya"),
      E("kontrol", "Kontrol 2–4 minggu", "kontrol"),
      E("vitamin_ganti_makan", "Suplemen vitamin bisa menggantikan sayur & buah", "pencegahan", "pengecoh", "Pola makan seimbang tetap utama.")],
     refs=[PPK])

CASE("defisiensi_mineral", GIZI,
     [IT("iodium", "Iodium", "utama", "Gondok endemik (daerah defisiensi iodium).", [O("kalium_iodida", "Kapsul minyak beriodium 200 mg dosis tunggal (sesuai program)", 200, "tunggal")], T("iodium")),
      IT("kalsium", "Kalsium", "utama", "Defisiensi kalsium.", [O("kalsium", "Kalsium karbonat 500–1000 mg/hari", (500, 1000), "rutin", (1, 2), (30, 90))], NT("iodium"))],
     [NP("garam", "Gunakan garam beryodium di rumah tangga", when=T("iodium")),
      NP("kalsium_makan", "Susu, ikan teri, tahu, sayur hijau & paparan matahari pagi", when=NT("iodium")),
      NP("gizi", "Pola makan seimbang"),
      NP("rujuk", "Rujuk bila gondok besar/nodular, sesak, atau tanda hipertiroid", when=T("iodium")),
      NP("pijat", "Pijat/urut benjolan gondok agar mengecil", "berbahaya", "Tidak bermanfaat; risiko perdarahan/cedera.")],
     [E("dx", "Keluhan disebabkan kekurangan mineral (iodium/kalsium) dari makanan", "diagnosis"),
      E("obat", "Suplemen diminum sesuai dosis & perbaiki pola makan", "pengobatan"),
      E("bahaya", "Segera kembali bila sesak/sulit menelan, berdebar, gemetar, atau kram/kejang otot", "tanda_bahaya"),
      E("kontrol", "Kontrol 1–3 bulan", "kontrol"),
      E("garam_kasar", "Garam krosok tanpa yodium lebih sehat", "pencegahan", "pengecoh", "Tidak mengandung iodium.")],
     refs=[PPK])

CASE("dislipidemia", META,
     [IT("statin", "Statin", "utama", "Menurunkan LDL & risiko kardiovaskular.",
         [O("simvastatin", "Simvastatin 20–40 mg malam hari", (20, 40), "rutin", (1, 1), (30, 30)),
          O("atorvastatin", "Atorvastatin 10–20 mg 1 × sehari", (10, 20), "rutin", (1, 1), (30, 30))], NT("tg_tinggi")),
      IT("fibrat", "Fibrat", "utama", "Hipertrigliseridemia menonjol.",
         [O("gemfibrozil", "Gemfibrozil 2 × 300 mg sebelum makan (atau 600 mg 1–2 × sehari)", (300, 600), "rutin", (1, 2), (30, 30))], T("tg_tinggi"))],
     [NP("diet", "Diet rendah lemak jenuh & trans, perbanyak serat"),
      NP("olahraga", "Olahraga aerobik 150 menit/minggu"),
      NP("bb", "Turunkan berat badan", when=T("obesitas_menyertai")),
      NP("rokok", "Berhenti merokok", when=T("merokok")),
      NP("stop", "Hentikan obat kolesterol bila hasil lab sudah normal", "berbahaya", "Kadar kembali naik; risiko kardiovaskular.")],
     [E("dx", "Ini dislipidemia: kadar lemak darah tidak normal, faktor risiko penyakit jantung & stroke", "diagnosis"),
      E("obat", "Obat diminum setiap hari jangka panjang bersama perubahan pola hidup", "pengobatan"),
      E("es", "Laporkan nyeri/lemah otot atau air kencing gelap (efek samping statin)", "efek_samping"),
      E("bahaya", "Segera ke IGD bila nyeri dada, sesak, kelemahan sesisi, atau bicara pelo", "tanda_bahaya"),
      E("kontrol", "Cek profil lipid 4–12 minggu setelah terapi", "kontrol"),
      E("minyak_ikan", "Cukup minum kapsul minyak ikan, obat tidak perlu", "pengobatan", "pengecoh", "Tidak menggantikan statin pada risiko tinggi.")],
     kie=["diagnosis", "pengobatan", "efek_samping", "tanda_bahaya", "kontrol"], refs=[PPK, "PERKI. Panduan Tata Laksana Dislipidemia (2022)"])

CASE("hiperurisemia", "Penyakit Dalam — nyeri sendi & otot",
     [IT("antiinflamasi", "Antiinflamasi serangan akut", "utama", "Artritis gout akut.",
         [O("kolkisin", "Kolkisin 0,5 mg 2–3 × sehari selama 3–7 hari", 0.5, "rutin", (2, 3), (3, 7)),
          O("natrium_diklofenak", "Natrium diklofenak 2–3 × 50 mg sesudah makan selama 5–7 hari", 50, "rutin", (2, 3), (5, 7)),
          O("ibuprofen", "Ibuprofen 3 × 400 mg sesudah makan selama 5–7 hari", 400, "rutin", (3, 3), (5, 7), forms="ibuprofen-tab400"),
          O("prednison", "Prednison 30 mg/hari selama 5 hari (bila OAINS/kolkisin kontraindikasi)", (20, 40), "rutin", (1, 1), (5, 5))]),
      IT("alopurinol", "Penurun asam urat", "opsional", "≥ 2 serangan/tahun atau tofus — dimulai/dilanjutkan dengan proteksi antiinflamasi.",
         [O("alopurinol", "Alopurinol mulai 100 mg/hari, titrasi hingga asam urat < 6 mg/dL", (100, 300), "rutin", (1, 1), (30, 30), forms="alopurinol-tab100")])],
     [NP("istirahat", "Istirahatkan & elevasi sendi, kompres dingin"),
      NP("diet", "Diet rendah purin (kurangi jeroan, daging merah, seafood), hindari alkohol & minuman manis, cukup minum"),
      NP("ult", "Rencanakan terapi penurun asam urat jangka panjang (alopurinol)", whenAny=[T("berulang"), T("tofus")]),
      NP("tiazid", "Ganti diuretik tiazid dengan antihipertensi lain", when=T("diuretik")),
      NP("pijat", "Pijat keras sendi yang bengkak", "berbahaya", "Memperberat inflamasi.")],
     [E("dx", "Ini asam urat tinggi dengan serangan radang sendi (gout)", "diagnosis"),
      E("obat", "Obat antiradang diminum sampai serangan reda; obat penurun asam urat diminum rutin jangka panjang bila diresepkan", "pengobatan"),
      E("es", "Kolkisin dapat menyebabkan diare; OAINS diminum sesudah makan", "efek_samping"),
      E("bahaya", "Segera kembali bila demam tinggi dengan sendi sangat merah (curiga infeksi), nyeri pinggang/kencing berdarah, atau ruam kulit setelah alopurinol", "tanda_bahaya"),
      E("kontrol", "Kontrol 1–2 minggu & cek asam urat berkala", "kontrol"),
      E("sayur", "Sayur bayam & kacang-kacangan penyebab utama asam urat", "pencegahan", "pengecoh", "Purin nabati jauh kurang berpengaruh dibanding jeroan/seafood/alkohol.")],
     avoid=[AV("Aspirin/salisilat meningkatkan kadar asam urat.", groups=["salisilat"]), AV("Tiazid meningkatkan asam urat.", drugs=["hidroklorotiazid"])],
     kie=["diagnosis", "pengobatan", "efek_samping", "tanda_bahaya", "kontrol"], refs=[PPK, "PRI. Rekomendasi Diagnosis & Pengelolaan Gout (2018)"])

CASE("obesitas", GIZI, [],
     [NP("defisit", "Defisit energi 500–750 kkal/hari; kurangi gula, gorengan, minuman manis (Isi Piringku)"),
      NP("aktivitas", "Aktivitas fisik 150–300 menit/minggu + latihan kekuatan"),
      NP("perilaku", "Catat makanan, tidur cukup, kelola stres"),
      NP("komorbid", "Skrining & kelola komorbid (tekanan darah, gula, lemak darah)"),
      NP("osa", "Rujuk evaluasi sleep apnea", when=T("osa")),
      NP("pelangsing", "Minum obat pelangsing/teh detoks tanpa resep", "berbahaya", "Kandungan tidak jelas (diuretik, sibutramin) — risiko jantung & ginjal.")],
     [E("dx", "Ini obesitas: kelebihan lemak tubuh yang meningkatkan risiko diabetes, hipertensi, & penyakit jantung", "diagnosis"),
      E("obat", "Kunci pengobatan adalah perubahan pola makan & aktivitas; target turun 5–10% BB dalam 6 bulan", "pengobatan"),
      E("bahaya", "Segera periksa bila nyeri dada, sesak, mendengkur dengan henti napas, atau sering haus & kencing", "tanda_bahaya"),
      E("kontrol", "Kontrol & timbang tiap bulan", "kontrol"),
      E("puasa_total", "Tidak makan sama sekali selama berhari-hari agar cepat kurus", "pengobatan", "berbahaya", "Kehilangan otot, hipoglikemia, & efek yoyo.")],
     avoid=[AV("Diuretik bukan obat penurun berat badan.", drugs=["hidroklorotiazid"])],
     note="Tatalaksana gaya hidup — tidak memerlukan resep obat di FKTP.", refs=[PPK, "Kemenkes RI. Pedoman Tata Laksana Obesitas Dewasa (2015)"])
